// Some portions generated by Claude
import { useState } from "react";
import type { UnreadableWorkspace } from "./use-stored-workspace.ts";

/**
 * Says that the graph saved for this repository could not be opened (the page opened without it), and offers to
 * recover what can be read of it or to delete it. Styled like the label guidance above the graph.
 */
export function UnreadableWorkspaceNotice({ state, onRecover, onDiscard }: {
  state: UnreadableWorkspace;
  onRecover: () => Promise<void>;
  onDiscard: () => Promise<void>;
}) {
  const [working, setWorking] = useState(false);
  if (!state) return null;
  const run = (action: () => Promise<void>) => {
    setWorking(true);
    void action().finally(() => setWorking(false));
  };
  return <section className="label-guidance" aria-label="Saved graph that could not be opened">
    <p>
      {state === "recoverable"
        ? "The graph saved here could not be opened as it was, so it is kept aside. Recover what can be read of it " +
          "(it replaces the graph shown; Undo brings that back), or delete it."
        : "Nothing in the saved graph that could not be opened can be read. Delete it to free the browser's storage."}
    </p>
    <div className="label-guidance-actions">
      {state === "recoverable" && (
        <button type="button" className="workbench-action workbench-action--secondary" disabled={working}
          onClick={() => run(onRecover)}>
          Recover
        </button>
      )}
      <button type="button" className="workbench-action workbench-action--ghost" disabled={working}
        title="Delete the saved graph that could not be opened from this browser" onClick={() => run(onDiscard)}>
        Delete
      </button>
    </div>
  </section>;
}
